import{_ as a,b as t,e as n,a8 as i}from"./chunks/framework.CNHV3T2x.js";const u=JSON.parse('{"title":"Unit GR32_Backends","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Backends","entity":"GR32_Backends","kind":"Unit","summary":"Provides interface contracts, abstraction layers, helper routines, and exception types for TBitmap32 surface backends.","date":1787871433000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Backends/index.md","filePath":"api/GR32_Backends/index.md","lastUpdated":1787871433000,"timestamp":1787871433000,"datetime":"2026-08-27T22:57:13.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),r={name:"api/GR32_Backends/index.md"};function o(c,e,s,d,p,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="unit-gr32-backends" tabindex="-1">Unit GR32_Backends <a class="header-anchor" href="#unit-gr32-backends" aria-label="Permalink to &quot;Unit GR32_Backends&quot;">​</a></h1><p>The <code>GR32_Backends</code> unit defines the core interface contracts, helper routines, and exception types for surface backend management in Graphics32. Backends abstract raw pixel buffer allocations, device context access, text rendering capabilities, canvas integration, and platform-specific surface operations.</p><hr><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><ul><li><a href="/api/GR32_Backends/EBackend/">EBackend</a>: Exception class raised when backend allocation or initialization fails.</li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><ul><li><a href="/api/GR32_Backends/IBitmapContextSupport">IBitmapContextSupport</a>: Interface for backends providing DIB bitmap headers and handles.</li><li><a href="/api/GR32_Backends/ICanvasSupport">ICanvasSupport</a>: Interface for backends providing VCL/LCL <code>TCanvas</code> integration.</li><li><a href="/api/GR32_Backends/IDeviceContextSupport">IDeviceContextSupport</a>: Interface for backends providing native OS device context handles (<code>HDC</code>) and drawing routines.</li><li><a href="/api/GR32_Backends/IFontHintingSupport">IFontHintingSupport</a>: Interface for configuring text font hinting settings (deprecated).</li><li><a href="/api/GR32_Backends/IFontSupport">IFontSupport</a>: Interface for backends managing font configuration and font change notifications.</li><li><a href="/api/GR32_Backends/IInteroperabilitySupport">IInteroperabilitySupport</a>: Interface for backends supporting pixel buffer copying from VCL/LCL <code>TGraphic</code> objects.</li><li><a href="/api/GR32_Backends/IPaintSupport">IPaintSupport</a>: Interface for backends executing repainting operations onto <code>TCanvas</code> controls.</li><li><a href="/api/GR32_Backends/ITextSupport">ITextSupport</a>: Interface for backends executing GDI/LCL text rendering and measurement.</li><li><a href="/api/GR32_Backends/ITextToPathSupport">ITextToPathSupport</a>: Interface for converting rendered text glyph outlines into vector paths.</li><li><a href="/api/GR32_Backends/ITextToPathSupport2">ITextToPathSupport2</a>: Extended interface for text-to-path conversion with advanced layout parameters.</li><li><a href="/api/GR32_Backends/IUpdateRectSupport">IUpdateRectSupport</a>: Interface for retrieving invalid rectangular regions from window controls.</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><ul><li><a href="/api/GR32_Backends/TTextHinting">TTextHinting</a>: Enumeration specifying text font hinting modes.</li><li><a href="/api/GR32_Backends/TRequireOperatorMode">TRequireOperatorMode</a>: Logical combination mode (<code>romAnd</code>, <code>romOr</code>) for querying required backend interface support.</li></ul><h2 id="routines" tabindex="-1">Routines <a class="header-anchor" href="#routines" aria-label="Permalink to &quot;Routines&quot;">​</a></h2><ul><li><a href="/api/GR32_Backends/RequireBackendSupport">RequireBackendSupport</a>: Verifies if a bitmap&#39;s active backend supports required interface contracts, switching to a suitable backend if necessary.</li><li><a href="/api/GR32_Backends/RestoreBackend">RestoreBackend</a>: Restores a previously saved backend instance onto a bitmap target.</li></ul>',11)])])}const h=a(r,[["render",o]]);export{u as __pageData,h as default};
